// checks = [{ name, status: 'up' | 'degraded' | 'down' }]
// État global attendu :
//   'down'      s'il existe au moins un service 'down' ;
//   sinon 'degraded' s'il existe au moins un service 'degraded' ;
//   sinon 'up'.
// SYMPTÔME de l'incident : le tableau de bord affiche 'up' alors que des
// services sont 'degraded'. Le rollup ne distingue que up/down.
export function aggregateHealth(checks) {
  const anyDown = checks.some((c) => c.status === 'down');
  return anyDown ? 'down' : 'up';
}

